Quick pretest before I explain. In SN2 the nucleophile brings a pair of electrons to carbon, while Br leaves carrying the C-Br bonding pair. Slide the nucleophile around the carbon and watch where the electron pairs sit.

```show_widget
<div style="font-family:system-ui,sans-serif;max-width:420px">
<svg id="s" viewBox="0 0 400 250" width="100%" role="img" aria-label="Nucleophile approaching a carbon bonded to bromine; slider changes approach angle">
  <line x1="180" y1="130" x2="235" y2="130" stroke="currentColor" stroke-width="3"/>
  <line x1="180" y1="130" x2="148" y2="95" stroke="currentColor" stroke-width="2"/>
  <line x1="180" y1="130" x2="148" y2="165" stroke="currentColor" stroke-width="2"/>
  <circle cx="148" cy="95" r="9" fill="none" stroke="currentColor"/><text x="148" y="99" text-anchor="middle" font-size="11" fill="currentColor">R</text>
  <circle cx="148" cy="165" r="9" fill="none" stroke="currentColor"/><text x="148" y="169" text-anchor="middle" font-size="11" fill="currentColor">R</text>
  <circle cx="180" cy="130" r="14" fill="none" stroke="currentColor" stroke-width="2"/><text x="180" y="135" text-anchor="middle" font-size="13" fill="currentColor">C</text>
  <circle cx="207" cy="130" r="2.5" fill="#D85A30"/><circle cx="213" cy="130" r="2.5" fill="#D85A30"/>
  <circle cx="245" cy="130" r="14" fill="#D85A30" fill-opacity=".25" stroke="#D85A30" stroke-width="2"/><text x="245" y="135" text-anchor="middle" font-size="12" fill="currentColor">Br</text>
  <line id="path" x1="0" y1="0" x2="180" y2="130" stroke="#378ADD" stroke-dasharray="4 4"/>
  <circle id="nu" r="14" fill="#378ADD" fill-opacity=".25" stroke="#378ADD" stroke-width="2"/>
  <text id="nut" text-anchor="middle" font-size="12" fill="currentColor">Nu</text>
  <circle id="lp1" r="2.5" fill="#378ADD"/><circle id="lp2" r="2.5" fill="#378ADD"/>
  <text x="200" y="240" text-anchor="middle" font-size="12" fill="currentColor" id="lab"></text>
</svg>
<input id="a" type="range" min="0" max="180" value="90" step="1" style="width:100%" aria-label="Approach angle">
<div style="display:flex;justify-content:space-between;font-size:12px;opacity:.8"><span>left of C (opposite Br)</span><span>right (Br side)</span></div>
<div style="font-size:12px;opacity:.7;margin-top:6px">Simplified 2D picture: dots are the electron pairs in play (blue: Nu lone pair, orange: C-Br bond). Ignores orbital shapes.</div>
</div>
<script>
const a=document.getElementById('a');
function upd(){
  const t=a.value*Math.PI/180, R=105, cx=180, cy=130;
  const x=cx-R*Math.cos(t), y=cy-R*Math.sin(t);
  const set=(id,o)=>{const e=document.getElementById(id);for(const k in o)e.setAttribute(k,o[k]);};
  set('nu',{cx:x,cy:y});set('nut',{x:x,y:y+4});
  set('path',{x1:x,y1:y});
  const ux=(cx-x)/R, uy=(cy-y)/R;
  const px=-uy, py=ux;
  set('lp1',{cx:x+ux*20+px*4,cy:y+uy*20+py*4});
  set('lp2',{cx:x+ux*20-px*4,cy:y+uy*20-py*4});
  document.getElementById('lab').textContent='Nu approaches at '+(180-a.value)+'\u00b0 from the C\u2013Br axis';
}
a.addEventListener('input',upd);upd();
</script>
```

The label shows the angle between the incoming nucleophile and the C-Br bond (180° means directly opposite Br).

Which approach would you choose so that Nu can bond to carbon while Br leaves in one smooth step, and what do you think goes wrong at the other end of the slider?
